#!/bin/sh
set -eu

# Download and verify official Google stock recovery archives for the exact
# admitted Pixel 9a target. This script only writes generated files below the
# ignored target-local recovery folder; it never contacts the device and never
# invokes adb or fastboot.

root=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
target="$root/targets/boards/google-pixel-9a-tegu-gxq96-mp1-0"
pins="$target/recovery.pins"
out="$target/recovery"

need() {
  command -v "$1" >/dev/null 2>&1 || {
    echo "missing $1" >&2
    exit 1
  }
}

need curl
if command -v shasum >/dev/null 2>&1; then
  hash_tool=shasum
else
  need sha256sum
  hash_tool=sha256sum
fi

sha256_of() {
  if [ "$hash_tool" = shasum ]; then
    shasum -a 256 "$1" | awk '{ print $1 }'
  else
    sha256sum "$1" | awk '{ print $1 }'
  fi
}

field() {
  kind=$1
  number=$2
  awk -F '\t' -v wanted="$kind" -v column="$number" \
    '$1 == wanted { print $column; exit }' "$pins"
}

download_one() {
  kind=$1
  filename=$(field "$kind" 4)
  url=$(field "$kind" 5)
  expected_hash=$(field "$kind" 6)
  expected_bytes=$(field "$kind" 7)
  source_page=$(field "$kind" 8)
  [ -n "$filename" ] && [ -n "$url" ] && [ -n "$expected_hash" ] && [ -n "$expected_bytes" ] || {
    echo "missing or malformed $kind pin in $pins" >&2
    exit 1
  }
  case "$url" in
    https://dl.google.com/dl/android/aosp/*) ;;
    *) echo "refusing non-Google recovery URL: $url" >&2; exit 1 ;;
  esac

  final="$out/$filename"
  part="$final.part"
  mkdir -p "$out"

  if [ -f "$final" ]; then
    actual_hash=$(sha256_of "$final")
    actual_bytes=$(wc -c < "$final" | tr -d '[:space:]')
    if [ "$actual_hash" = "$expected_hash" ] && [ "$actual_bytes" = "$expected_bytes" ]; then
      printf 'verified existing %s (%s bytes)\n' "$final" "$actual_bytes"
      return 0
    fi
    echo "existing file failed verification; replacing only generated path: $final" >&2
    rm -f "$final"
  fi

  printf 'downloading %s from %s\n' "$kind" "$url"
  curl --fail --location --retry 3 --connect-timeout 30 --output "$part" "$url"
  actual_bytes=$(wc -c < "$part" | tr -d '[:space:]')
  [ "$actual_bytes" = "$expected_bytes" ] || {
    echo "size mismatch for $filename: expected $expected_bytes, got $actual_bytes" >&2
    rm -f "$part"
    exit 1
  }
  actual_hash=$(sha256_of "$part")
  [ "$actual_hash" = "$expected_hash" ] || {
    echo "SHA-256 mismatch for $filename: expected $expected_hash, got $actual_hash" >&2
    rm -f "$part"
    exit 1
  }
  mv "$part" "$final"
  printf 'verified %s (%s bytes, sha256 %s)\n' "$final" "$actual_bytes" "$actual_hash"
  printf 'source: %s\n' "$source_page"
}

case "${1:-all}" in
  all) download_one factory; download_one ota ;;
  factory|ota) download_one "$1" ;;
  *) echo "usage: $0 [all|factory|ota]" >&2; exit 2 ;;
esac

manifest="$out/download-manifest.txt"
{
  printf '# Generated by tools/pixel-9a/recovery-download.sh\n'
  printf '# Target: google-pixel-9a-tegu-gxq96-mp1-0\n'
  printf '# Files are generated and ignored; do not commit them.\n'
  for kind in factory ota; do
    filename=$(field "$kind" 4)
    final="$out/$filename"
    if [ -f "$final" ]; then
      printf '%s\t%s\t%s\t%s\n' "$kind" "$filename" "$(wc -c < "$final" | tr -d '[:space:]')" "$(sha256_of "$final")"
    fi
  done
} > "$manifest"
printf 'manifest: %s\n' "$manifest"
